import { getDictCmdbList, getDictCmdbListPid, getDictList } from "@/api/dict";
import { update } from "@/api/device/hardwarebasictree";
export default {
  props: ['isShow', 'arrtId', 'type', 'formDetial'],
  data: function data() {
    return {
      loading: false,
      saveLoading: false,
      deviceCategoryList: null,
      deviceTypeList: null,
      yesnoList: null,
      rules: {
        parentCiId: [{
          required: true,
          message: '父模型ID不能为空',
          trigger: 'blur'
        }],
        ciId: [{
          required: true,
          message: '模型ID不能为空',
          trigger: 'blur'
        }],
        ciLabel: [{
          required: true,
          message: '模型英文不能为空',
          trigger: 'blur'
        }],
        ciName: [{
          required: true,
          message: '模型名称不能为空',
          trigger: 'blur'
        }],
        level: [{
          required: true,
          message: '当前层级不能为空',
          trigger: 'blur'
        }],
        isMenu: [{
          required: true,
          message: '显示树形不能为空',
          trigger: 'blur'
        }],
        isMap: [{
          required: true,
          message: '属性映射不能为空',
          trigger: 'blur'
        }],
        isUpdate: [{
          required: true,
          message: '属性层级不能为空',
          trigger: 'blur'
        }]
      }
    };
  },
  mounted: function mounted() {
    this.initDict();
  },
  methods: {
    submit: function submit() {
      var _this = this;
      this.saveLoading = true;
      update(this.formDetial).then(function () {
        _this.$emit('refreshData');
        _this.$emit('close');
        _this.$message({
          type: "success",
          message: "操作成功!"
        });
      }).finally(function () {
        _this.saveLoading = false;
      });
    },
    initDict: function initDict() {
      var _this2 = this;
      this.loading = true;
      //设备分类
      getDictCmdbList({
        ciId: 1097745625841664
      }).then(function (res) {
        _this2.loading = false;
        _this2.deviceCategoryList = res.data;
      });
      this.loading = true;
      //设备类型
      getDictCmdbListPid({
        ciId: 1097745969774592,
        pid: this.formDetial.deviceClaccify
      }).then(function (res) {
        _this2.loading = false;
        _this2.deviceTypeList = res.data;
      });
      this.loading = true;
      //yes or no menu
      getDictList('tree_is_menu').then(function (res) {
        _this2.loading = false;
        _this2.yesnoList = res.data;
      });
    },
    elSelectVis: function elSelectVis(val, list, type) {
      var _this3 = this;
      if (val) {
        if (list && list.length > 0) {
          return;
        }
        if (type === 'tree_is_menu') {
          //yes or no menu
          getDictList('tree_is_menu').then(function (res) {
            _this3.yesnoList = res.data;
          });
        } else if (type === 'deviceClaccify') {
          //设备分类
          getDictCmdbList({
            ciId: 1097745625841664
          }).then(function (res) {
            _this3.deviceCategoryList = res.data;
          });
        } else if (type === 'deviceType') {
          //设备类型
          if (!this.formDetial.deviceClaccify) {
            this.$message.warning('请先选择设备分类');
            this.deviceTypeList = [];
            return;
          }
          getDictCmdbListPid({
            ciId: 1097745969774592,
            pid: this.formDetial.deviceClaccify
          }).then(function (res) {
            _this3.deviceTypeList = res.data;
          });
        }
      }
    },
    selChange: function selChange(value, type) {
      if (type === 'deviceClaccify') {
        //设备分类
        this.deviceTypeList = null;
        this.formDetial.deviceType = null;
        if (value != null && value != '') {
          this.elSelectVis(true, this.deviceTypeList, 'deviceType');
        }
      } else if (type === 'deviceType') {
        //设备类型
        this.$forceUpdate();
      }
    }
  }
};
